head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > mandatory]<br/>validate() 메소드로 컴포넌트의 입력값 유효성 체크 시 입력값의 유/무를 확인하도록 설정합니다.",
    "validation" : [
        "validate() 메소드로 컴포넌트의 입력값 유효성 체크 시 입력값의 유/무를 확인하도록 설정합니다.",
        "true 설정 시 컴포넌트의 입력값 유/무를 확인합니다.",
        "true 설정 시 'w2textarea_mandatory' 클래스가 추가됩니다.",
        "false (기본값) 설정 시 컴포넌트의 입력값 유/무를 확인하지 않습니다.",
        "미설정 시 기본값 false 로 동작합니다.",
        "컴포넌트에 입력값이 없는 경우 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 '필수 입력 항목입니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (mandatory 미설정 → 빈 값이어도 validate PASS, 기본값 false 동작)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2 (mandatory=false → 빈 값이어도 validate PASS)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


// target3 (mandatory=true, 빈 값 → validate FAIL, displaymessage=true 이므로 invalidMessage alert 출력)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}


// target4 (mandatory=true, 값 있음 → validate PASS)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("입력값 있음");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}


// target5 (mandatory=true, displaymessage=true, invalidMessage/invalidMessageFunc 미설정 → 엔진 기본 메시지 '필수 입력 항목입니다' alert)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}


// target6 (mandatory=true → render 에 'w2textarea_mandatory' 클래스 추가 확인)
scwin.btn_checkClass6_onclick = function (e) {
    let hasClass = target6.render.classList.contains("w2textarea_mandatory");
    wf_body_bottom.getObj("scwin").setReturnValue("w2textarea_mandatory class : " + hasClass);
}


// target7 (mandatory=false → render 에 'w2textarea_mandatory' 클래스 미추가 확인)
scwin.btn_checkClass7_onclick = function (e) {
    let hasClass = target7.render.classList.contains("w2textarea_mandatory");
    wf_body_bottom.getObj("scwin").setReturnValue("w2textarea_mandatory class : " + hasClass);
}
